CREATE TABLE public.sales_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL DEFAULT public.current_store_id() REFERENCES public.stores(id),number text NOT NULL,kind text NOT NULL CHECK(kind IN ('quotation','invoice','credit_note')),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','converted','cancelled')),customer_id uuid REFERENCES public.customers(id),customer_name text NOT NULL DEFAULT '',currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','ZiG','ZAR')),exchange_rate numeric NOT NULL DEFAULT 1,lines jsonb NOT NULL DEFAULT '[]',subtotal numeric NOT NULL DEFAULT 0,discount numeric NOT NULL DEFAULT 0,total numeric NOT NULL DEFAULT 0,due_date date,notes text NOT NULL DEFAULT '',sale_id uuid REFERENCES public.sales(id),refund_id uuid REFERENCES public.refunds(id),source_id uuid REFERENCES public.sales_documents(id),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,number));
GRANT SELECT ON public.sales_documents TO authenticated; GRANT ALL ON public.sales_documents TO service_role;
ALTER TABLE public.sales_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.sales_documents FOR SELECT TO authenticated USING(store_id=public.current_store_id() AND public.is_staff(auth.uid()));
CREATE UNIQUE INDEX one_invoice_per_sale ON public.sales_documents(sale_id) WHERE kind='invoice';
CREATE UNIQUE INDEX one_credit_per_refund ON public.sales_documents(refund_id) WHERE kind='credit_note';
CREATE TRIGGER store_ownership_guard BEFORE INSERT OR UPDATE ON public.sales_documents FOR EACH ROW EXECUTE FUNCTION public.assign_store_ownership();
CREATE TABLE public.document_counters(store_id uuid NOT NULL REFERENCES public.stores(id),kind text NOT NULL,value bigint NOT NULL DEFAULT 0,PRIMARY KEY(store_id,kind));
GRANT ALL ON public.document_counters TO service_role; ALTER TABLE public.document_counters ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.next_document_number(p_kind text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v bigint; sid uuid:=public.current_store_id(); BEGIN IF sid IS NULL OR NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; IF p_kind NOT IN ('quotation','invoice','credit_note') THEN RAISE EXCEPTION 'Invalid document type'; END IF; INSERT INTO public.document_counters(store_id,kind,value) VALUES(sid,p_kind,1) ON CONFLICT(store_id,kind) DO UPDATE SET value=document_counters.value+1 RETURNING value INTO v; RETURN CASE p_kind WHEN 'quotation' THEN 'QT-' WHEN 'invoice' THEN 'INV-' ELSE 'CN-' END||lpad(v::text,6,'0'); END $$;
REVOKE ALL ON FUNCTION public.next_document_number(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.next_document_number(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_sales_document(p_id uuid,p_kind text,p_customer uuid,p_currency text,p_lines jsonb,p_discount numeric,p_due date,p_notes text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid:=public.current_store_id(); d record; line jsonb; product record; snap jsonb:='[]'; sub numeric:=0; qty numeric; price numeric; rate numeric; cname text:=''; result uuid; BEGIN
IF NOT public.is_staff(auth.uid()) OR p_kind NOT IN ('quotation','invoice') THEN RAISE EXCEPTION 'Not authorised'; END IF;
IF p_id IS NOT NULL THEN SELECT * INTO d FROM public.sales_documents WHERE id=p_id AND store_id=sid FOR UPDATE; IF NOT FOUND OR d.status<>'draft' OR d.kind<>p_kind THEN RAISE EXCEPTION 'Only your draft documents can be edited'; END IF; END IF;
IF p_customer IS NOT NULL THEN SELECT name INTO cname FROM public.customers WHERE id=p_customer AND store_id=sid AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found'; END IF; END IF;
SELECT public.currency_rate(p_currency,zig_rate,rand_rate) INTO rate FROM public.settings WHERE store_id=sid;
IF jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)=0 OR jsonb_array_length(p_lines)>200 THEN RAISE EXCEPTION 'Add between 1 and 200 lines'; END IF;
FOR line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP SELECT * INTO product FROM public.products WHERE id=(line->>'product_id')::uuid AND store_id=sid AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Product not found'; END IF; qty:=(line->>'quantity')::numeric; price:=coalesce((line->>'unit_price')::numeric,product.selling_price); IF qty IS NULL OR qty<=0 OR price<0 OR qty::text='NaN' OR price::text='NaN' THEN RAISE EXCEPTION 'Invalid quantity or price'; END IF; IF price<>product.selling_price AND NOT public.has_permission(auth.uid(),'override_price') THEN RAISE EXCEPTION 'Price override not allowed'; END IF; sub:=sub+round(qty*price,2); snap:=snap||jsonb_build_array(jsonb_build_object('product_id',product.id,'name',product.name,'quantity',qty,'unit_price',price,'line_total',round(qty*price,2))); END LOOP;
IF p_discount IS NULL OR p_discount<0 OR p_discount>sub OR (p_discount>0 AND NOT public.has_permission(auth.uid(),'give_discount')) THEN RAISE EXCEPTION 'Invalid or unauthorised discount'; END IF;
IF p_id IS NULL THEN INSERT INTO public.sales_documents(number,kind,customer_id,customer_name,currency,exchange_rate,lines,subtotal,discount,total,due_date,notes) VALUES(public.next_document_number(p_kind),p_kind,p_customer,coalesce(cname,''),p_currency,rate,snap,sub,p_discount,sub-p_discount,p_due,coalesce(p_notes,'')) RETURNING id INTO result; ELSE UPDATE public.sales_documents SET customer_id=p_customer,customer_name=coalesce(cname,''),currency=p_currency,exchange_rate=rate,lines=snap,subtotal=sub,discount=p_discount,total=sub-p_discount,due_date=p_due,notes=coalesce(p_notes,''),updated_at=now() WHERE id=p_id RETURNING id INTO result; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.save_sales_document(uuid,text,uuid,text,jsonb,numeric,date,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_sales_document(uuid,text,uuid,text,jsonb,numeric,date,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.convert_quote_to_invoice(p_document uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d record; result uuid; BEGIN SELECT * INTO d FROM public.sales_documents WHERE id=p_document AND store_id=public.current_store_id() FOR UPDATE; IF NOT FOUND OR d.kind<>'quotation' OR d.status='cancelled' OR NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Quotation not available'; END IF; SELECT id INTO result FROM public.sales_documents WHERE source_id=d.id AND kind='invoice'; IF FOUND THEN RETURN result; END IF; IF d.due_date<current_date THEN RAISE EXCEPTION 'Quotation has expired'; END IF; INSERT INTO public.sales_documents(number,kind,customer_id,customer_name,currency,exchange_rate,lines,subtotal,discount,total,due_date,notes,source_id) VALUES(public.next_document_number('invoice'),'invoice',d.customer_id,d.customer_name,d.currency,d.exchange_rate,d.lines,d.subtotal,d.discount,d.total,NULL,d.notes,d.id) RETURNING id INTO result; UPDATE public.sales_documents SET status='converted',updated_at=now() WHERE id=d.id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.convert_quote_to_invoice(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.convert_quote_to_invoice(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.post_sales_invoice(p_document uuid,p_payments jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d record; result jsonb; items jsonb; s record; BEGIN SELECT * INTO d FROM public.sales_documents WHERE id=p_document AND store_id=public.current_store_id() FOR UPDATE; IF NOT FOUND OR d.kind<>'invoice' OR NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Invoice not found'; END IF; IF d.sale_id IS NOT NULL THEN RETURN jsonb_build_object('id',d.sale_id,'duplicate',true); END IF; IF d.status<>'draft' THEN RAISE EXCEPTION 'Invoice is not a draft'; END IF; IF d.customer_id IS NULL THEN RAISE EXCEPTION 'Choose a customer for this invoice'; END IF; SELECT jsonb_agg(jsonb_build_object('product_id',x->>'product_id','quantity',x->'quantity','price',x->'unit_price')) INTO items FROM jsonb_array_elements(d.lines) x; result:=public.complete_sale(items,p_payments,d.discount,d.currency,d.customer_id); SELECT * INTO s FROM public.sales WHERE id=(result->>'id')::uuid; UPDATE public.sales_documents SET sale_id=s.id,status='issued',exchange_rate=s.exchange_rate,subtotal=s.subtotal,total=s.total,updated_at=now() WHERE id=d.id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.post_sales_invoice(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.post_sales_invoice(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.issue_sale_invoice(p_sale uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; result uuid; snap jsonb; cname text; BEGIN SELECT * INTO s FROM public.sales WHERE id=p_sale AND store_id=public.current_store_id() FOR UPDATE; IF NOT FOUND OR NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Sale not found'; END IF; SELECT id INTO result FROM public.sales_documents WHERE sale_id=p_sale AND kind='invoice'; IF FOUND THEN RETURN result; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('product_id',product_id,'name',name,'quantity',quantity,'unit_price',unit_price,'line_total',line_total)),'[]'::jsonb) INTO snap FROM public.sale_items WHERE sale_id=p_sale; SELECT name INTO cname FROM public.customers WHERE id=s.customer_id; INSERT INTO public.sales_documents(number,kind,status,customer_id,customer_name,currency,exchange_rate,lines,subtotal,discount,total,sale_id) VALUES(public.next_document_number('invoice'),'invoice','issued',s.customer_id,coalesce(cname,''),s.currency,s.exchange_rate,snap,s.subtotal,s.discount,s.total,s.id) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.issue_sale_invoice(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.issue_sale_invoice(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.cancel_sales_document(p_document uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; UPDATE public.sales_documents SET status='cancelled',updated_at=now() WHERE id=p_document AND store_id=public.current_store_id() AND status='draft' AND sale_id IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Only draft documents can be cancelled'; END IF; END $$;
REVOKE ALL ON FUNCTION public.cancel_sales_document(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cancel_sales_document(uuid) TO authenticated;
ALTER TABLE public.refunds ADD COLUMN returned_lines jsonb NOT NULL DEFAULT '[]';
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.refund_sale(uuid,jsonb,text,text)'::regprocedure) INTO d; d:=replace(d,'v_shift uuid;','v_shift uuid; v_refund uuid; v_lines jsonb:=''[]'';'); d:=replace(d,'where id = p_sale for update','where id = p_sale AND store_id=public.current_store_id() for update'); d:=replace(d,'for it in select * from jsonb_array_elements(p_items) loop','IF public.is_cash_method(p_method) AND NOT EXISTS(SELECT 1 FROM public.cashier_shifts WHERE cashier_id=v_uid AND status=''open'' AND store_id=public.current_store_id()) THEN RAISE EXCEPTION ''Open your shift for cash refunds''; END IF; IF public.is_account_method(p_method) AND (v_sale.customer_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.sale_payments WHERE sale_id=p_sale AND public.is_account_method(method))) THEN RAISE EXCEPTION ''Account credit requires an account sale''; END IF; for it in select * from jsonb_array_elements(p_items) loop'); d:=replace(d,'update sale_items set refunded_qty','v_lines:=v_lines||jsonb_build_array(jsonb_build_object(''sale_item_id'',si.id,''product_id'',si.product_id,''name'',si.name,''quantity'',v_qty,''unit_price'',si.unit_price,''line_total'',round(si.unit_price*v_qty,2))); update sale_items set refunded_qty'); d:=replace(d,'refunded_by, shift_id) values','refunded_by, shift_id,returned_lines) values'); d:=replace(d,'v_uid, v_shift);','v_uid, v_shift,v_lines) RETURNING id INTO v_refund;'); d:=replace(d,'jsonb_build_object(''amount'', v_amt)','jsonb_build_object(''amount'', v_amt,''refund_id'',v_refund)'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.issue_credit_note(p_refund uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; s record; result uuid; cname text; BEGIN SELECT * INTO r FROM public.refunds WHERE id=p_refund AND store_id=public.current_store_id() FOR UPDATE; IF NOT FOUND OR NOT public.can_refund(auth.uid()) THEN RAISE EXCEPTION 'Refund not available'; END IF; SELECT id INTO result FROM public.sales_documents WHERE refund_id=p_refund; IF FOUND THEN RETURN result; END IF; IF jsonb_array_length(r.returned_lines)=0 THEN RAISE EXCEPTION 'This older refund has no item snapshot; issuance is blocked'; END IF; SELECT * INTO s FROM public.sales WHERE id=r.sale_id; SELECT name INTO cname FROM public.customers WHERE id=s.customer_id; INSERT INTO public.sales_documents(number,kind,status,customer_id,customer_name,currency,exchange_rate,lines,subtotal,total,notes,sale_id,refund_id) VALUES(public.next_document_number('credit_note'),'credit_note','issued',s.customer_id,coalesce(cname,''),s.currency,s.exchange_rate,r.returned_lines,r.amount,r.amount,r.reason,s.id,r.id) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.issue_credit_note(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.issue_credit_note(uuid) TO authenticated;